/**
 * 支线任务种子库（结构化数据）
 *
 * 历史上种子写在 SKILL.md 正文里，是散文式清单，机器和人都不好检索。
 * 现在每条种子是一条带完整标签的记录，供：
 *   1. S1 入场时由 renderSeedCatalog() 渲染成紧凑清单注入模型上下文；
 *   2. 后续按玩家档案（时长/场景/体力/人群）做服务端硬筛或加权排序；
 *   3. 维护时按维度统计、增补、去重。
 * 标签口径与 SKILL.md《怎么用》一节一致；种子只做灵感来源，禁止原样照抄。
 */

export type SeedMechanism =
  | '随机委托' // 把决定权交给随机：硬币/骰子/随机数
  | '收集图鉴' // 定主题集齐 N 个
  | '视角重赋' // 给寻常物一个新身份
  | '规则限制' // 给平常事加一条奇怪约束
  | '定点观察' // 固定位置记录变化和细节
  | '触感心流' // 重复手部动作让脑子关机
  | '盲盒猜谜' // 屏蔽一种感官/信息靠猜
  | '角色扮演' // 换一个身份做平常事
  | '连接动作' // 发起一次微小的人际接触
  | '留痕收尾'; // 产出一件可回看的证据

export type SeedCategory = 'explore' | 'organize' | 'create' | 'connect' | 'sense';

export type SeedScene = '户外' | '店' | '场馆' | '家' | '工位' | '通勤' | '雨天' | '夜' | '任何';

export type SeedPeople = '独' | '双' | '众';

/** 人群标签：特别适合谁；不填表示谁都合适 */
export type SeedAudience = 'i人' | 'e人' | '情侣' | '朋友' | '亲子' | '祖孙' | '打工人';

export type SeedGroup =
  | 'outdoor' // 户外·街上·公园
  | 'shop' // 店里·商场·花市
  | 'venue' // 场馆·寺庙·文化空间
  | 'home' // 家里·一个人
  | 'craft' // 手工·做点东西
  | 'social' // 和人一起
  | 'rainNight' // 雨天·夜晚
  | 'work'; // 工位·通勤·碎片

export interface Seed {
  id: string;
  title: string;
  /** 一句话玩法（含产物/数量锚点），渲染给模型看 */
  text: string;
  group: SeedGroup;
  mech: SeedMechanism;
  cat: SeedCategory;
  scenes: SeedScene[];
  /** 预计时长（分钟） */
  min: number;
  people: SeedPeople[];
  /** 预算：0 = 零成本，低 = 小额消费（材料/门票/交通） */
  budget: '0' | '低';
  /** 体力：坐 = 几乎不动，慢 = 慢走/慢节奏，动 = 中高强度 */
  energy: '坐' | '慢' | '动';
  who?: SeedAudience[];
  /** 创意程度：1 = 经典稳妥，2 = 有点新鲜，3 = 脑洞陌生化 */
  nov: 1 | 2 | 3;
}

const S = (s: Seed) => s;

