// ── 渲染 ────────────────────────────────────────────────────────────

const GROUP_LABELS: Record<SeedGroup, string> = {
  outdoor: '户外·街上·公园',
  shop: '店里·商场·花市',
  venue: '场馆·寺庙·文化空间',
  home: '家里·一个人',
  craft: '手工·做点东西',
  social: '和人一起·情侣/朋友/家人',
  rainNight: '雨天·夜晚',
  work: '工位·通勤·碎片',
};

const GROUP_ORDER: SeedGroup[] = ['outdoor', 'shop', 'venue', 'home', 'craft', 'social', 'rainNight', 'work'];

const CAT_LABELS: Record<SeedCategory, string> = {
  explore: '探索',
  organize: '整理',
  create: '创造',
  connect: '连接',
  sense: '感官',
};

/**
 * 渲染成注入模型上下文的紧凑目录。按场景分组，每条一行，标签可硬筛。
 * 格式：〈机制·类别·时长·场景·人数·预算·体力·人群·新意N〉
 */
export function renderSeedCatalog(): string {
  const lines: string[] = [];
  lines.push(`## 支线种子目录（结构化 · 共 ${SEEDS.length} 条，按场景分组）`);
  lines.push('');
  lines.push('每条标签：〈机制·类别·时长·场景·人数·预算·体力·人群·新意〉。');
  lines.push('类别：探索/整理/创造/连接/感官；新意：1=经典稳妥、2=有点新鲜、3=脑洞陌生化；人群只在特别适合某类玩家时标注。');
  lines.push('用法不变：先按玩家时长/场景/人数/预算/体力硬筛，再借机制改编，禁止原样照抄；一组 2-4 个活动至少跨两种机制。');
  lines.push('');

  for (const group of GROUP_ORDER) {
    const seeds = SEEDS.filter((s) => s.group === group);
    if (seeds.length === 0) continue;
    lines.push(`### ${GROUP_LABELS[group]}（${seeds.length}）`);
    for (const s of seeds) {
      const tags = [
        s.mech,
        CAT_LABELS[s.cat],
        `${s.min}min`,
        s.scenes.join('/'),
        s.people.join(''),
        s.budget === '0' ? '0元' : '低消',
        s.energy,
        s.who && s.who.length ? s.who.join('/') : '',
        `新意${s.nov}`,
      ].filter(Boolean);
      lines.push(`- ${s.title}：${s.text} 〈${tags.join('·')}〉`);
    }
    lines.push('');
  }

  return lines.join('\n').trim();
}
